const m = ($input.first().json.message && $input.first().json.message.content) || {};
const tasks = $('Get Open Tasks').first().json;
const arr = Array.isArray(tasks) ? tasks : [];
const task = arr.find(t => t.id === m.task_id) || null;
return [{ json: { task_id: m.task_id || null, task } }];

const expenses = $('Status: Get Stats').first().json || [];
const incomes = $('Status: Get Incomes').first().json || [];
const debts = $('Status: Get Debts').first().json || [];
const goals = $input.first().json || [];
const TZ = 'Asia/Almaty';
const now = new Date();
const todayStart = new Date(new Date().toLocaleDateString('en-CA', {timeZone:TZ}) + 'T00:00:00+05:00');
const weekStart = new Date(Date.now() - 7*86400000);
const monthStart = new Date(Date.now() - 30*86400000);
const sum = (arr, field) => arr.reduce((s,x)=>s+Number(x[field]||0),0);
const filterDate = (arr, field, from) => arr.filter(x => new Date(x[field]) >= from);
const expArr = Array.isArray(expenses) ? expenses : [];
const incArr = Array.isArray(incomes) ? incomes : [];
const debtArr = Array.isArray(debts) ? debts : [];
const goalArr = Array.isArray(goals) ? goals : [];
const stats = {
  expense_today: sum(filterDate(expArr,'occurred_at',todayStart),'amount'),
  expense_week: sum(filterDate(expArr,'occurred_at',weekStart),'amount'),
  expense_month: sum(filterDate(expArr,'occurred_at',monthStart),'amount'),
  income_today: sum(filterDate(incArr,'received_at',todayStart),'amount'),
  income_week: sum(filterDate(incArr,'received_at',weekStart),'amount'),
  income_month: sum(filterDate(incArr,'received_at',monthStart),'amount'),
  balance_month: sum(filterDate(incArr,'received_at',monthStart),'amount') - sum(filterDate(expArr,'occurred_at',monthStart),'amount'),
  debts_active: debtArr.filter(d => !d.is_closed).map(d => ({name:d.name, remaining:Number(d.current_balance), initial:Number(d.initial_amount), monthly:Number(d.monthly_payment||0), currency:d.currency})),
  goals: goalArr.map(g => ({name:g.name, current:Number(g.current_amount), target:Number(g.target_amount), pct:g.target_amount>0?Math.round(g.current_amount/g.target_amount*100):0, currency:g.currency, target_date:g.target_date})),
};
return [{ json: stats }];
